// This script is generated by Gemini
using UnityEngine;
using System.Collections; 

public class Dumpster : MonoBehaviour
{
    [Header("Dumpster Settings")]
    public Transform player;
    public float interactionRadius = 2.5f;
    [Tooltip("Use this to move the interaction circle down to the floor or out to the front")]
    public Vector3 interactionOffset = new Vector3(0, -1f, 0);
    
    [Header("Mesh Animation (8 PNGs)")]
    [Tooltip("Drag the object with the Mesh Renderer here")]
    public MeshRenderer dumpsterMesh;
    [Tooltip("Drag your 8 PNGs here in order")]
    public Texture2D[] animationFrames;
    public float framesPerSecond = 12f;
    private bool isAnimating = false;

    [Header("Audio")]
    public AudioSource dumpAudio;

    void Start()
    {
        if (player == null)
        {
            GameObject playerObj = GameObject.FindGameObjectWithTag("Player");
            if (playerObj != null) player = playerObj.transform;
        }
    }

    void Update()
    {
        if (player == null || ScoreManager.Instance == null) return;

        // Calculate the new offset center point
        Vector3 centerPoint = transform.position + interactionOffset;
        
        // Flatten the Y axis so the distance check is a perfect cylinder
        Vector3 flatPlayerPosition = new Vector3(player.position.x, centerPoint.y, player.position.z);
        float distance = Vector3.Distance(centerPoint, flatPlayerPosition);

        if (distance <= interactionRadius && ScoreManager.Instance.currentBagLoad > 0)
        {
            EmptyTrashBag();
        }
    }

    private void EmptyTrashBag()
    {
        ScoreManager.Instance.EmptyBag();
        
        if (dumpAudio != null) 
        {
            dumpAudio.Play();
        }
        
        if (!isAnimating && dumpsterMesh != null && animationFrames.Length > 0)
        {
            StartCoroutine(PlayTextureAnimation());
        }
        
        Debug.Log("Dumpster Emptied!");
    }

    private IEnumerator PlayTextureAnimation()
    {
        isAnimating = true;
        float delay = 1f / framesPerSecond;

        for (int i = 0; i < animationFrames.Length; i++)
        {
            dumpsterMesh.material.mainTexture = animationFrames[i];
            yield return new WaitForSeconds(delay);
        }

        dumpsterMesh.material.mainTexture = animationFrames[0];
        isAnimating = false;
    }

    void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.blue;
        // Draw the gizmo at the new offset position so you can actually see it
        Gizmos.DrawWireSphere(transform.position + interactionOffset, interactionRadius);
    }
}